    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createCandidate>>, TError,{electionId: number;data: BodyType<CandidateInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createCandidate>>, TError,{electionId: number;data: BodyType<CandidateInput>}, TContext> => {

const mutationKey = ['createCandidate'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createCandidate>>, {electionId: number;data: BodyType<CandidateInput>}> = (props) => {
          const {electionId,data} = props ?? {};

          return  createCandidate(electionId,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateCandidateMutationResult = NonNullable<Awaited<ReturnType<typeof createCandidate>>>
    export type CreateCandidateMutationBody = BodyType<CandidateInput>
    export type CreateCandidateMutationError = ErrorType<unknown>

    /**
 * @summary Add candidate to election
 */
export const useCreateCandidate = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createCandidate>>, TError,{electionId: number;data: BodyType<CandidateInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof createCandidate>>,
        TError,
        {electionId: number;data: BodyType<CandidateInput>},
        TContext
      > => {
      return useMutation(getCreateCandidateMutationOptions(options));
    }

